function quote(s){
const escaped=s.replace(/\\/g,"\\\\").replace(/[!"#$%&'()*+,\-./:;<=>?@[\]^_`{|}~]/g,"\\$&");
return '**"'+escaped+'"**';
}

function longestBackticks(s){return Math.max(0,...Array.from(s.matchAll(/`+/g),m=>m[0].length));}

function buildResponse(plan){
 if(plan.kind==="direct")return plan.response;
 const L=longestBackticks(plan.text),K=Math.max(3,L+1),fence="`".repeat(K);
 let r=fence+"text\n"+plan.text+"\n"+fence;
 if(plan.kind==="edit")r+="\n\nChanges:\n"+plan.changes.map(([a,b,why])=>"- "+quote(a)+" → "+quote(b)+": "+why).join("\n");
 return r;
}

function checkEdits(plans){
 return Object.entries(plans).filter(([,p])=>p.kind==="edit").map(([id,p])=>{
  let reconstructed=p.source;
  for(const [before,after] of p.changes)reconstructed=reconstructed.replace(before,after);
  return {id,all_edits_accounted_for:reconstructed===p.text,paragraph_and_line_breaks_preserved:(p.source.match(/\n/g)||[]).length===(p.text.match(/\n/g)||[]).length};
 });
}

function checkDraft(plans){
 const p=plans["new-draft"];
 return {id:"new-draft",sentence_count:(p.text.match(/[.!?]+(?:\s|$)/g)||[]).length,inventory:p.fact_inventory,fact_check:p.fact_check};
}

function checkLiteralFormatting(plans){
 const out=[];
 for(const [id,p] of Object.entries(plans)){
  if(p.kind!=="edit")continue;
  const tokens=p.source.match(/https?:\/\/[^\s)]+|www\.[^\s,]+|\b[\w]+@[\w.]+|`[^`\n]+`|\*\*[^*\n]+\*\*|(?<!\*)\*[^*\n]+\*(?!\*)|~~[^~\n]+~~|<[^>\n]+>|&[a-z]+;/g)||[];
  out.push({id,source_tokens:tokens,all_source_tokens_retained:tokens.every(token=>p.text.includes(token))});
 }
 return out;
}

