function escapeHTML(s){return s.replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}

function renderInline(s){
 let out="",i=0,strong=false;
 while(i<s.length){
  if(s[i]==="\\"&&i+1<s.length&&/[!"#$%&'()*+,\-./:;<=>?@[\]\\^_`{|}~]/.test(s[i+1])){out+=escapeHTML(s[i+1]);i+=2;}
  else if(s.slice(i,i+2)==="**"){out+=strong?"</strong>":"<strong>";strong=!strong;i+=2;}
  else if(s[i]==="`"){const end=s.indexOf("`",i+1);if(end!==-1){out+="<code>"+escapeHTML(s.slice(i+1,end))+"</code>";i=end+1;}else{out+="`";i++;}}
  else{out+=escapeHTML(s[i]);i++;}
 }
 if(strong)throw Error("Unbalanced strong emphasis");
 return out;
}

function renderMarkdown(markdown){
 const lines=markdown.split("\n");let out="",i=0;
 while(i<lines.length){
  if(!lines[i]){i++;continue;}
  const fence=lines[i].match(/^(`{3,})text$/);
  if(fence){
   const marker=fence[1];let content=[];i++;
   while(i<lines.length&&lines[i]!==marker)content.push(lines[i++]);
   if(i===lines.length)throw Error("Unclosed fence");
   out+='<pre><code class="language-text">'+escapeHTML(content.join("\n"))+"</code></pre>\n";i++;continue;
  }
  if(lines[i].startsWith("- ")){
   out+="<ul>\n";
   while(i<lines.length&&lines[i].startsWith("- "))out+="<li>"+renderInline(lines[i++].slice(2))+"</li>\n";
   out+="</ul>\n";continue;
  }
  let p=[];
  while(i<lines.length&&lines[i]&&!lines[i].startsWith("- "))p.push(lines[i++]);
  out+="<p>"+renderInline(p.join("\n"))+"</p>\n";
 }
 return out;
}
